ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2 ImageFileName=/\\(bcdedit|vssadmin|wbadmin|wmic)\.exe$/i
| regex("(?i)(safeboot\\s+(minimal|network)|set\\s+\\{(default|current)\\}\\s+safeboot|delete\\s+shadows|delete\\s+catalog|delete\\s+systemstatebackup|shadowcopy\\s+delete)", field=CommandLine)
| case {
    ImageFileName=/bcdedit\.exe$/i | safeboot_hit := 1 ;
    * | recovery_hit := 1
  }
| groupBy([aid, ComputerName], function={ sum(safeboot_hit, as=sb) | sum(recovery_hit, as=rd) | collect([ImageFileName, CommandLine]) })
| sb > 0 AND rd > 0
